const inputItems = $input.all();

/*
 * Parse one CSV line while respecting quoted values.
 * Example:
 * MIG001,Sales Analytics,"ADF, ADLS",High
 */
function parseCsvLine(line) {
  const values = [];
  let current = '';
  let insideQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (char === '"') {
      // Handle escaped quote: ""
      if (insideQuotes && line[i + 1] === '"') {
        current += '"';
        i++;
      } else {
        insideQuotes = !insideQuotes;
      }
    } else if (char === ',' && !insideQuotes) {
      values.push(current.trim());
      current = '';
    } else {
      current += char;
    }
  }

  values.push(current.trim());

  return values;
}


/*
 * Convert the strange Extract-from-File output:
 *
 * {
 *   "project_id,application_name,...":
 *   "MIG001,Sales Analytics,..."
 * }
 *
 * into a normal JSON object.
 */
function parseExtractedItem(json) {

  // If n8n already parsed the CSV properly,
  // simply use the object as-is.
  if (json.project_id) {
    return json;
  }

  const keys = Object.keys(json);

  if (keys.length !== 1) {
    throw new Error(
      `Unexpected CSV structure: ${JSON.stringify(json)}`
    );
  }

  const headerLine = keys[0];
  const dataLine = json[headerLine];

  const headers = parseCsvLine(headerLine);
  const values = parseCsvLine(dataLine);

  if (headers.length !== values.length) {
    throw new Error(
      `CSV column mismatch. Headers=${headers.length}, Values=${values.length}`
    );
  }

  const parsed = {};

  headers.forEach((header, index) => {
    parsed[header] = values[index];
  });

  return parsed;
}


function normalizeSourcePlatform(value) {
  const v = (value || '').trim().toLowerCase();

  if (v === 'hd insight' || v === 'hdinsight') {
    return 'HDInsight';
  }

  if (v === 'azure data factory') {
    return 'Azure Data Factory';
  }

  if (v === 'azure synapse analytics') {
    return 'Azure Synapse Analytics';
  }

  if (v === 'power bi') {
    return 'Power BI';
  }

  if (v === 'azure databricks') {
    return 'Azure Databricks';
  }

  return value ? value.trim() : value;
}


function normalizeBusinessCriticality(value) {
  const v = (value || '').trim().toLowerCase();

  if (v === 'high') return 'High';
  if (v === 'medium') return 'Medium';
  if (v === 'low') return 'Low';

  return value ? value.trim() : value;
}


function normalizeDependencies(value) {
  if (Array.isArray(value)) {
    return value.map(v => v.trim());
  }

  return (value || '')
    .split(';')
    .map(v => v.trim())
    .filter(Boolean)
    .map(v => {
      const lower = v.toLowerCase();

      if (lower === 'adf') return 'ADF';
      if (lower === 'adls') return 'ADLS';
      if (lower === 'adls gen2') return 'ADLS Gen2';
      if (lower === 'sql db') return 'SQL DB';
      if (lower === 'event hubs') return 'Event Hubs';

      return v;
    });
}


return inputItems.map(inputItem => {

  const item = parseExtractedItem(inputItem.json);

  return {
    json: {
      project_id: item.project_id,
      application_name: item.application_name,
      source_platform: normalizeSourcePlatform(item.source_platform),
      workload_type: item.workload_type,
      data_size_gb: Number(item.data_size_gb),
      daily_jobs: Number(item.daily_jobs),
      dependencies: normalizeDependencies(item.dependencies),
      business_criticality:
        normalizeBusinessCriticality(item.business_criticality),
      current_issues: item.current_issues,
      target_platform: item.target_platform
    }
  };
});
